/* --- 纯白舞曲 (White Waltz) v5感谢代码楼里老师们的代码https://discord.com/channels/1291925535324110879/1380392618336194702
感谢尾老师，类名，输入框伪提示词来自尾老师，hy老师的去除思维链箭头，na老师的悬浮底栏和思维链文字自定义，楼层信息自定义，12的去思维链背景色。感谢NA老师的去阴影，感谢咩野老师的去除全局阴影. - */

/* --- 1. 字体导入 --- */
@import url('https://fonts.googleapis.com/css2?family=Great+Vibes&display=swap'); 
@import url("https://fontsapi.zeoseven.com/796/main/result.css"); 
@import url("https://fontsapi.zeoseven.com/253/main/result.css"); 

@font-face {
    font-family: 'Keaiquan';
    src: url('https://cdn.jsdelivr.net/gh/loud23for-ship-it/ziti@main/keaiquan.woff2') format('woff2');
    font-weight: normal;
    font-style: normal;
    font-display: swap;
}

@font-face {
    font-family: 'MeiGuiYuSanWen';
    src: url('https://cdn.jsdelivr.net/gh/loud23for-ship-it/ziti@main/meiguiyusanwen.woff2') format('woff2');
    font-weight: normal;
    font-style: normal;
    font-display: swap;
}

/* --- 2. 核心颜色与样式变量 --- */
:root {
    --theme-bg: #F5F6F7;
    --panel-bg-color: rgba(238, 238, 238, 0.85);
    --panel-bg-hover: rgba(221, 222, 224, 0.95);
    --card-bg: rgba(255, 255, 255, 0.9);
    --input-bg: rgba(238, 238, 238, 0.9);
    --text-main: #2D3748;
    --text-subtle: #718096;
    --border-color: rgba(215, 216, 218, 0.6);
    --accent-color: #B0C4DE;
    --selected-color: #9EB3CD;
    --font-english: "Great Vibes", cursive;
    --font-main: "Keaiquan", var(--font-english);
    --font-quote: "MeiGuiYuSanWen", var(--font-english);
    --font-code: "Hangeuljaemin4.0", monospace;
    --font-title: "JasonHandwriting1", var(--font-english);
    --border-radius: 16px;
}

/* --- 3. 全局样式 --- */
body { background-color: var(--theme-bg) !important; color: var(--text-main); font-family: var(--font-main); }
#sheld, #character_view { background: transparent !important; margin: 0 auto !important; left: 0; right: 0; border: none !important; box-shadow: none !important; overflow: visible !important; }
#chat { background: transparent !important; align-items: center !important; padding-bottom: 120px !important; }
h1, h2, h3, h4, .standoutHeader, .inline-drawer-header, .title_restorable { font-family: var(--font-title); color: var(--text-main); }

/* --- 4. 顶部导航栏 & 挂件 --- */
#top-settings-holder { position:relative; background-color: var(--panel-bg-color); backdrop-filter: blur(8px); box-shadow: none; border: none; }
#top-settings-holder::after { content: ''; display: block; width: 80px; height: 100px; background-image: url('https://tc-new.z.wiki/autoupload/1N2_UJVYUo2KjM-_22IFnCfNcKcqEnRmcljopnyJoMs/20260226/NWmI/1229X1607/2026-02-26_112202.png/webp'); background-size: contain; background-repeat: no-repeat; position: absolute; bottom: -85px; left: 20px; pointer-events: none; z-index: 100; }

.drawer-icon.fa-fw::before { content: '' !important; font-size: 0 !important; }
.drawer-icon.fa-fw { width: 35px; height: 40px; background-size: contain; background-repeat: no-repeat; background-position: center; transition: transform 0.3s ease; }
.drawer-icon.fa-fw:hover { transform: scale(1.1); }
#ai-config-button .drawer-icon, .drawer-icon.fa-sliders, #advanced-formatting-button .drawer-icon, .drawer-icon.fa-font, #user-settings-button .drawer-icon, .drawer-icon.fa-user, #extensions-settings-button .drawer-icon, .drawer-icon.fa-cubes, #persona-management-button .drawer-icon, .drawer-icon.fa-face-smile { background-image: url('https://tc-new.z.wiki/autoupload/1N2_UJVYUo2KjM-_22IFnCfNcKcqEnRmcljopnyJoMs/20260226/O9EX/1402X1245/2026-02-26_112300.png/webp'); }
#sys-settings-button .drawer-icon, .drawer-icon.fa-plug, #WI-SP-button .drawer-icon, .drawer-icon.fa-book-atlas, .drawer-icon.fa-image, .drawer-icon.fa-panorama, #character_popup_button .drawer-icon, .drawer-icon.fa-address-card, #table_database_settings_drawer .drawer-icon, .drawer-icon.fa-bars-progress { background-image: url('https://tc-new.z.wiki/autoupload/1N2_UJVYUo2KjM-_22IFnCfNcKcqEnRmcljopnyJoMs/20260226/7f16/1300X1465/2026-02-26_112228.png/webp'); }
.drawer-content { background-image: url('https://tc-new.z.wiki/autoupload/1N2_UJVYUo2KjM-_22IFnCfNcKcqEnRmcljopnyJoMs/20260226/mu85/1200X900/a92390d26b3e113064aee976f1af46d3.jpg/webp'); background-size: cover; background-position: center; border: none; border-radius: var(--border-radius); box-shadow: none; }

/* --- 5. 底部悬浮输入栏 --- */
#send_textarea::placeholder { color: transparent !important; opacity: 0 !important; }
#send_textarea::-webkit-input-placeholder { color: transparent !important; opacity: 0 !important; }
#form_sheld { position: absolute !important; bottom: 15px !important; left: 0; right: 0; display: flex; justify-content: center; z-index: 1000; pointer-events: none; }
#send_form { pointer-events: auto; width: 90% !important; max-width: 800px !important; margin: 0 auto !important; border-radius: 25px !important; background-color: var(--input-bg) !important; padding: 10px 15px !important; backdrop-filter: blur(10px) !important; -webkit-backdrop-filter: blur(10px) !important; border: 1px solid var(--border-color) !important; box-shadow: 0 4px 20px rgba(0, 0, 0, 0.05) !important; transition: all 0.5s ease !important; position: relative; }
#send_form:hover { transform: translateY(-5px) !important; background-color: var(--panel-bg-hover) !important; box-shadow: 0 8px 30px rgba(0, 0, 0, 0.1) !important; border: 1px solid var(--accent-color) !important; }
#rightSendForm, #leftSendForm { gap: 10px; }
#send_textarea { clip-path: none !important; border: none !important; background: transparent !important; color: var(--text-main) !important; }
#nonQRFormItems:has(#send_textarea:placeholder-shown)::before { content: "于纯白乐章上，落笔..."; color: var(--text-subtle); position: absolute; top: 50%; left: 50%; transform: translate(-50%, -50%); font-family: var(--font-main); font-size: 0.5em; pointer-events: none; z-index: 10; white-space: nowrap; }
#options_button::before, #send_but::before, #send_form #extensionsMenuButton::before, #ai_retry_button::before, #auto_completion_button::before { display: none !important; }
#options_button, #send_but, #send_form #extensionsMenuButton, #ai_retry_button, #auto_completion_button { width: 32px; height: 32px; background-size: contain; background-repeat: no-repeat; background-position: center; transition: transform 0.2s ease; font-size: 0; border: none; background-color: transparent; }
#options_button:hover, #send_but:hover, #send_form #extensionsMenuButton:hover, #ai_retry_button:hover, #auto_completion_button:hover { transform: scale(1.1); }
#options_button, #ai_retry_button { background-image: url('https://tc-new.z.wiki/autoupload/1N2_UJVYUo2KjM-_22IFnCfNcKcqEnRmcljopnyJoMs/20260226/x3qr/1107X1519/2026-02-26_112246.png/webp'); }
#send_form #extensionsMenuButton { background-image: url('https://tc-new.z.wiki/autoupload/1N2_UJVYUo2KjM-_22IFnCfNcKcqEnRmcljopnyJoMs/20260226/fd3r/1573X1138/2026-02-26_112336.png/webp'); }
#send_but { background-image: url('https://tc-new.z.wiki/autoupload/1N2_UJVYUo2KjM-_22IFnCfNcKcqEnRmcljopnyJoMs/20260226/Fd0t/1722X1617/2026-02-26_113506.png/webp'); }
#auto_completion_button { background-image: url('https://tc-new.z.wiki/autoupload/1N2_UJVYUo2KjM-_22IFnCfNcKcqEnRmcljopnyJoMs/20260226/7DIP/1467X1509/2026-02-26_112312.png/webp'); }

/* --- 6. 核心：消息布局与样式 --- */
.mes { display: flex; flex-direction: column; padding: 0 !important; margin: 45px auto 40px !important; width: 85%; max-width: 700px; background: transparent !important; border: none !important; box-shadow: none !important; overflow: visible !important; position: relative; }
.mes .mesAvatarWrapper {
    display: flex; justify-content: center; align-items: center; padding: 0;
    border-radius: var(--border-radius) var(--border-radius) 0 0;
    width: 100%;
    background-size: cover; background-position: center;
    position: relative; z-index: 5;
    height: 180px !important; 
    min-height: 180px !important;
    overflow: visible !important;
}
.mes[is_user="true"] .mesAvatarWrapper { background-image: url('https://tc-new.z.wiki/autoupload/1N2_UJVYUo2KjM-_22IFnCfNcKcqEnRmcljopnyJoMs/20260226/HJYA/4578X2298/2026-02-26_110850.png/webp'); }
.mes[is_user="false"] .mesAvatarWrapper { background-image: url('https://tc-new.z.wiki/autoupload/1N2_UJVYUo2KjM-_22IFnCfNcKcqEnRmcljopnyJoMs/20260226/JCJc/4578X2298/2026-02-26_110616.png/webp'); }
.mes .avatar {
    position: absolute;
    top: 50%; left: 50%;
    transform: translate(-50%, -50%);
    width: 155px; height: 215px; 
    background-color: #FAFAFA !important;
    padding: 8px 8px 26px 8px !important; 
    border: 1px solid rgba(0,0,0,0.08) !important;
    box-shadow: 2px 6px 15px rgba(0, 0, 0, 0.15) !important; 
    z-index: 10;
    display: flex !important; 
    align-items: center;
    justify-content: center;
    border-radius: 2px !important;
}
.mes .avatar img {
    width: 100% !important; height: 100% !important;
    object-fit: cover !important; 
    border-radius: 0 !important; border: none !important;
    image-rendering: -webkit-optimize-contrast; 
    image-rendering: crisp-edges;
}
.mes .mesAvatarWrapper::after { 
    content: '';
    position: absolute;
    left: 50%; transform: translateX(-50%);
    z-index: 15;
    background-image: url('https://tc-new.z.wiki/autoupload/1N2_UJVYUo2KjM-_22IFnCfNcKcqEnRmcljopnyJoMs/20260226/l2zo/4578X2298/2026-02-26_114326.png/webp');
    background-size: contain; 
    background-repeat: no-repeat;
    background-position: center;
    bottom: -35px; 
    width: 330px; 
    height: 60px; 
}
.mes .mes_block {
    background-color: transparent !important; 
    background-image: 
        linear-gradient(to bottom, #ffffff 0%, #ffffff calc(100% - 150px), rgba(255, 255, 255, 0) 100%), 
        url('https://tc-new.z.wiki/autoupload/1N2_UJVYUo2KjM-_22IFnCfNcKcqEnRmcljopnyJoMs/20260226/mFzZ/1290X1704/2026-02-26_111901.png/webp');
    background-size: 100% 100%, 100% auto !important;
    background-position: center top, center bottom !important; 
    background-repeat: no-repeat !important; 
    border-radius: 0 0 var(--border-radius) var(--border-radius);
    padding: 80px 30px 45px !important; 
    margin-top: 0 !important; 
    position: relative;
    border: none;
    overflow: visible !important; 
    min-height: 150px !important; 
}

.mes .mes_text, .mes_reasoning { background: transparent !important; border: none !important; padding: 0 !important; margin: 0 !important; backdrop-filter: none !important; }
#chat .mes .mes_reasoning_header { background: transparent !important; border: none !important; box-shadow: none !important; border-radius: 0; backdrop-filter: none !important; padding: 0 !important; margin-bottom: 10px !important; display: inline-flex !important; align-items: center !important; }
.mes_reasoning_arrow { display: none !important; }
.mes_reasoning_header h4, .mes_reasoning_header_title { font-size: 0 !important; visibility: hidden; }
.mes_reasoning_header h4::before, .mes_reasoning_header_title::before { content: "旋律流转，思绪渐明"; font-family: var(--font-title); font-size: 14px !important; color: var(--accent-color); visibility: visible; }
.mes_reasoning { border-left: 3px solid var(--accent-color) !important; padding-left: 15px !important; margin-bottom: 20px !important; }
.mes .mes_text { line-height: 1.9; color: var(--text-main); }

/* 排版与文字特效系统 */
.mes_text h1 {
    font-family: var(--font-title);
    color: var(--text-main);
    font-size: 1.6em;
    text-align: center;
    position: relative;
    padding-bottom: 12px;
    margin: 30px 0 20px 0;
    border-bottom: 1px dashed rgba(176, 196, 222, 0.6);
    font-weight: normal;
}
.mes_text h1::after {
    content: '✧';
    position: absolute;
    bottom: -11px;
    left: 50%;
    transform: translateX(-50%);
    color: var(--accent-color);
    font-size: 14px;
    background: #ffffff; 
    padding: 0 12px;
}
.mes_text h2 {
    font-family: var(--font-title);
    color: var(--text-main);
    font-size: 1.3em;
    padding: 6px 0 6px 15px;
    border-left: 4px solid var(--accent-color);
    margin: 25px 0 15px 0;
    background: linear-gradient(to right, rgba(176, 196, 222, 0.15) 0%, transparent 100%);
    border-radius: 0 8px 8px 0;
    font-weight: normal;
}
.mes_text em, .mes_text i {
    font-family: var(--font-quote);
    font-style: italic !important;
    color: var(--italics_text_color); 
    background: rgba(245, 247, 250, 0.85); 
    padding: 2px 6px;
    border-radius: 6px;
    box-shadow: 0 1px 2px rgba(0, 0, 0, 0.02);
    margin: 0 2px;
}
.mes_text strong, .mes_text b {
    font-family: var(--font-title);
    color: var(--text-main);
    font-weight: bold;
    background-image: linear-gradient(transparent 60%, rgba(176, 196, 222, 0.45) 60%);
    background-repeat: no-repeat;
    background-size: 100% 100%;
    padding: 0 2px;
}
.mes_text blockquote {
    background-color: rgba(247, 250, 252, 0.7);
    border: 1px solid rgba(176, 196, 222, 0.25);
    border-left: 4px solid var(--accent-color);
    padding: 12px 18px;
    border-radius: 4px 12px 12px 4px;
    margin: 18px 0;
    font-family: var(--font-quote);
    color: var(--quote_text_color);
    position: relative;
    box-shadow: inset 0 0 10px rgba(255, 255, 255, 0.5);
}
.mes_text span.quote, .mes_text q, .mes_text .dialogue {
    font-family: var(--font-quote);
    color: var(--quote_text_color);
    text-shadow: 0 0 1px rgba(131, 146, 165, 0.15);
}
.mes_text code { font-family: var(--font-code); background-color: rgba(237, 242, 247, 0.8) !important; color: var(--text-main) !important; padding: 2px 6px; border-radius: 6px; border: 1px solid var(--border-color); }

.mes[is_user="false"] .mes_block::before {
    content: ''; display: block; position: absolute;
    top: -10px; left: -30px; 
    width: 100px; height: 65px;
    background-image: url('https://tc-new.z.wiki/autoupload/1N2_UJVYUo2KjM-_22IFnCfNcKcqEnRmcljopnyJoMs/20260226/U4Mz/2048X2048/2026-02-26_114127.png/webp');
    background-size: contain; background-repeat: no-repeat; pointer-events: none; z-index: 20;
    transform: scaleX(-1) rotate(-15deg); 
}
.mes[is_user="true"] .mes_block::after {
    content: ''; display: block; position: absolute;
    bottom: -30px; right: -25px; 
    width: 75px; height: 95px;
    background-image: url('https://tc-new.z.wiki/autoupload/1N2_UJVYUo2KjM-_22IFnCfNcKcqEnRmcljopnyJoMs/20260226/jlby/1326X1736/2026-02-26_112425.png/webp');
    background-size: contain; background-repeat: no-repeat; pointer-events: none; z-index: 20;
    opacity: 0.95;
    transform: rotate(-10deg);
}

/* =========================================================
   ✨ 最终功能修复：将楼层信息、时间戳与编辑按钮(小铅笔) 完美排列在正文上方
   适配 PC 端与手机端触屏
   ========================================================= */

/* 1. 隐藏多余的头像框名字，但必须保留正文框(mes_block)里的名字容器 */
.mes .mesAvatarWrapper > .ch_name { display: none !important; }

/* 2. 将 .ch_name 容器作为顶部信息栏，放置在 padding 预留的空白处 */
.mes .mes_block > .ch_name {
    display: flex !important; 
    position: absolute;
    top: 25px !important;    /* 固定在气泡顶端 */
    left: 30px !important;
    right: 30px !important;
    width: auto !important;
    justify-content: space-between !important; /* 左侧名字时间，右侧按钮 */
    align-items: flex-start !important;        /* 兼容手机端换行 */
    background: transparent !important;
    border: none !important;
    box-shadow: none !important;
    z-index: 100; 
    transform: none !important;
    padding: 0;
}

/* 3. 左侧：名字、楼层、时间戳容器 */
.mes .ch_name > .flex-container {
    display: flex !important;
    align-items: center !important;
    gap: 10px !important;
    flex-wrap: wrap !important; /* 手机端防遮挡 */
}

/* 如果你想单隐名字，把下面 color: var(--text-main) 改成 color: transparent */
.mes .ch_name .name_text { font-weight: bold; font-size: 13px !important; color: var(--text-main) !important; }

.mes .mesIDDisplay, .mes .mes_timer {
    position: static !important;  /* 移除之前的绝对定位，让他们排排坐 */
    color: var(--text-subtle) !important; 
    font-size: 12px !important; 
    line-height: 1 !important;
    transform: none !important;
}
.mes .mesIDDisplay { font-family: var(--font-title); }
.mesIDDisplay::before { content: '纯白舞步 · 第 '; }
.mesIDDisplay::after { content: ' 曲'; }

/* 4. 右侧：小铅笔、编辑按钮等 */
.mes .mes_buttons, .mes .mes_edit_buttons {
    /* 不强制覆盖 display，让 ST 自身的 JS 来切换铅笔和保存按钮 */
    flex-direction: row-reverse;
    gap: 8px;
    position: static !important; /* 跟着 flex 布局走，不乱飞 */
    opacity: 0.65;               /* 手机端保持常显且不刺眼 */
    transition: opacity 0.3s ease;
    pointer-events: auto !important;
}
.mes:hover .mes_buttons, .mes:hover .mes_edit_buttons {
    opacity: 1; /* PC端鼠标悬浮高亮 */
}
.mes .mes_buttons .mes_button, .mes .mes_edit_buttons .mes_button {
    background-color: rgba(238, 238, 238, 0.7) !important;
    backdrop-filter: blur(4px);
    color: var(--text-subtle) !important;
    padding: 6px !important;
    border-radius: 8px !important;
    cursor: pointer;
    transition: all 0.2s ease;
    font-size: 14px !important;
    height: auto !important;
    width: auto !important;
    line-height: 1 !important;
}
.mes .mes_buttons .mes_button:hover, .mes .mes_edit_buttons .mes_button:hover {
    background-color: var(--accent-color) !important;
    color: white !important;
    transform: scale(1.1);
}
/* ========================================================= */

#typing_indicator { background-image: url('https://tc-new.z.wiki/autoupload/1N2_UJVYUo2KjM-_22IFnCfNcKcqEnRmcljopnyJoMs/20260226/fd3r/1573X1138/2026-02-26_112336.png/webp') !important; background-size: contain !important; background-repeat: no-repeat !important; background-position: center !important; animation: pulse 1.5s infinite ease-in-out; border: none !important; height: 40px !important; width: 40px !important; margin: 10px auto !important; }
#typing_indicator .dot { display: none !important; }
@keyframes pulse { 0% { transform: scale(0.95); opacity: 0.7; } 50% { transform: scale(1.05); opacity: 1; } 100% { transform: scale(0.95); opacity: 0.7; } }

/* --- 全局UI --- */
* { box-shadow: none !important; border-style: solid; border-width: 0;}
.standoutHeader, .inline-drawer-header, .title_restorable, #extensions_settings2 > div, #extensions_settings > div, .openai_logit_bias_preset_form, details > summary, #power-user-options-block h4, #InstructSettingsColumn h4, #SystemPromptColumn h4, #ContextSettings h4, .persona_management_global_settings h4, #character_popup h4, #AdvancedFormatting h4, #rm_group_chats_block h4, div[name*='HandlingToggles'] h4, div[name*='MiscellaneousToggles'] h4 { background: var(--card-bg) !important; border-bottom: 1px solid var(--border-color) !important; border-radius: 8px !important; padding: 8px 12px !important; margin-bottom: 8px !important; color: var(--text-main) !important; }
input[type="text"], input[type="number"], input[type="search"], textarea, select, .text_pole { background-color: var(--input-bg) !important; border: 1px solid var(--border-color) !important; color: var(--text-main) !important; border-radius: 8px !important; }
input:focus, textarea:focus, select:focus { border-color: var(--accent-color) !important; }
.menu_button { background-color: var(--card-bg) !important; border: 1px solid var(--border-color) !important; color: var(--text-main) !important; transition: all 0.2s ease; }
.menu_button:hover { background-color: var(--accent-color) !important; border-color: var(--accent-color) !important; color: white !important; }
input[type="checkbox"]:checked::before { box-shadow: inset 1em 1em var(--accent-color) !important; }
dialog.popup { background-color: transparent !important; border: none !important; }
dialog.popup .popup-body, #dialogue_popup { background-image: url('https://tc-new.z.wiki/autoupload/1N2_UJVYUo2KjM-_22IFnCfNcKcqEnRmcljopnyJoMs/20260226/mu85/1200X900/a92390d26b3e113064aee976f1af46d3.jpg/webp') !important; background-size: cover !important; background-position: center !important; border: 1px solid var(--border-color) !important; border-radius: var(--border-radius) !important; position: relative; overflow: hidden; }
dialog.popup .popup-body::before, #dialogue_popup::before { content: ''; position: absolute; top: 0; left: 0; right: 0; bottom: 0; background-color: rgba(255, 255, 255, 0.7); backdrop-filter: blur(5px); z-index: 0; }
